edits.newText:
Base.iterate(w::Windows) = _first_window(w)

function Base.iterate(w::Windows, i)
    # i = 0-based start index of last yielded window; next = i+1
    @debug "iterate w $i len=$(length(w.v)) k=$(w.k)"
    if i + w.k ≤ length(w.v)
        (@view w.v[i+1:i+w.k]), i + 1
    else
        nothing
    end
end

function _first_window(w::Windows)
    n = length(w.v)
    @debug "_first_window len=$(n) k=$(w.k)"
    w.k > n && return nothing
    (@view w.v[1:w.k]), 0   # state 0 means "next window starts at index 0"
end

